def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != 0]
        if cols:
            for c in range(cols[0], cols[-1] + 1):
                if row[c] == 0:
                    out[r][c] = 2
    return out
